; [Menu] Processes menu state based on $00C9 value and dispatches.
ProcessMenuState:
        PHB
        PHP
        PHK
        PLB
        SEP #$20
        REP #$10
        JSR.W processMenuData
        LDA.W $00C9
        BNE handleGameMode1
        JSR.W updateContinueMenu
        JMP.W processMenuCancel
; [GameState] Handles game mode 1 logic. Entry: 8-bit A, 16-bit X/Y.
handleGameMode1:
        CMP.B #$01
        BNE handleGameMode2
        JMP.W processMenuCancel
; [GameState] Handles game mode 2 logic. Entry: 8-bit A, 16-bit X/Y.
handleGameMode2:
        CMP.B #$02
        BEQ handleGameMode5
        CMP.B #$03
        BNE handleGameMode3
        JSR.W updatePasswordDisplay
; [GameState] Handles game mode 3 logic. Entry: 8-bit A, 16-bit X/Y.
handleGameMode3:
        CMP.B #$05
        BEQ CODE_5FD17F
        JMP.W updateMenuLoad
CODE_5FD17F:
        JMP.W $DA3B
; [GameState] Handles game mode 5 logic. Entry: 8-bit A, 16-bit X/Y.
handleGameMode5:
        REP #$20
        INC.W $052A
        INC.W $052A
        LDA.W $0527
        CLC
        ADC.W #$0041
        STA.W $0527
        LDA.W $1E66
        CMP.W #$00F4
        BCS updateGameProgressValues
        INC.W $1E66
        INC.W $1E66
        INC.W $1E66
        INC.W $1E66
        JMP.W handleMenuNavigation
; [GameState] Updates game progress values. Entry: 16-bit A/X/Y.
updateGameProgressValues:
        SEP #$20
        LDA.B #$00
        XBA
        LDA.W $00D4
        ORA.W $00D5
        BEQ updateLevelState
        REP #$20
        LDX.W #$0000
; [GameState] Checks progress thresholds. Entry: 16-bit A/X/Y.
checkProgressThresholds:
        LDA.W $0310
        EOR.W #$5555
        STA.W $0310,X
        INX
        INX
        CPX.W #$000A
        BNE checkProgressThresholds
        SEP #$20
        LDA.B #$00
        XBA
        PLP
        PLB
        RTL
; [LevelLoad] Updates level state variables. Entry: 8-bit A, 16-bit X/Y.
updateLevelState:
        REP #$20
        PHB
        LDX.W #$D4B4
        LDY.W #$0200
        LDA.W #$005F
        MVN $00,$9F
        STZ.W $0310
        STZ.W $0312
        STZ.W $0314
        STZ.W $0316
        STZ.W $0318
        STZ.W $031A
        PLB
        REP #$20
        LDA.W $058A
        BIT.W #$5080
        BEQ handleLevelTransition
        LDA.W #$0026
        STA.W $1288
        JSL.L SetupDataProcessing80
; [Transition] Handles level transition logic. Entry: 16-bit A/X/Y.
handleLevelTransition:
        SEP #$20
        LDA.B #$00
        XBA
        LDA.W $058B
        BIT.B #$0F
        BEQ updateTransitionEffects
        LDA.B #$27
        STA.W $1288
        JSL.L SetupDataProcessing80
        LDA.B #$00
        XBA
; [Effects] Updates transition effects. Entry: 8-bit A, 16-bit X/Y.
updateTransitionEffects:
        LDA.W $1E00
        CMP.B #$02
        BCS processScreenFade
        db $AD,$8B,$05,$0D,$01,$1E,$29,$04,$8D,$01,$1E,$AD,$8B,$05,$4A,$29
        db $04,$49,$FF,$2D,$01,$1E,$8D,$01,$1E,$4C,$87,$D2
; [Effects] Processes screen fade effects. Entry: 8-bit A, 16-bit X/Y.
processScreenFade:
        LDA.W $058B
        AND.B #$01
        ORA.W $1E01
        STA.W $1E01
        LDA.W $058B
        LSR A
        AND.B #$01
        EOR.B #$FF
