        STA.W $1E01
        LDA.W $058B
        LSR A
        AND.B #$02
        BEQ updateFadeState
        CLC
        ADC.W $1E01
        CMP.B #$06
        BCS updateFadeState
        STA.W $1E01
; [Effects] Updates fade state variables. Entry: 8-bit A, 16-bit X/Y.
updateFadeState:
        LDA.W $058B
        LSR A
        LSR A
        AND.B #$02
        EOR.B #$FF
        INC A
        BEQ handleFadeCompletion
        CLC
        ADC.W $1E01
        BMI handleFadeCompletion
        STA.W $1E01
; [Effects] Handles fade completion logic. Entry: 8-bit A, 16-bit X/Y.
handleFadeCompletion:
