; [GameState] Checks game state flags and memory regions. Handles menu transitions, flag conditions, and memory validation. Entry: 8-bit A, 16-bit X/Y.
checkGameStateAndMemory:
        PHB
        PHP
        PHK
        PLB
        SEP #$20
        REP #$10
        JSL.L handleMenuTransition
        LDA.W $00C9
        BNE handleFlagConditions
        LDA.W $00C8
        CMP.B #$1A
        BEQ checkGameFlags
        JSR.W handleVoicePlayback
        JMP.W handleFlagConditions
; [GameState] Checks game flags $D4/$D5. Entry: 8-bit A, 16-bit X/Y.
checkGameFlags:
        JSR.W updateAudioResources
; [GameState] Handles flag conditions and branches. Entry: 8-bit A, 16-bit X/Y.
handleFlagConditions:
        LDA.W $00D4
        ORA.W $00D5
        BEQ checkMemoryRegions
        JMP.W handleSpecialCondition
; [Memory] Checks memory regions $06F0-$07F2. Entry: 16-bit A, 16-bit X/Y.
checkMemoryRegions:
        REP #$20
        LDA.W $06F0
        ORA.W $06F2
        ORA.W $07F0
        ORA.W $07F2
        BNE processMemoryCheck
        STA.B $00
        LDA.W $058A
        AND.W #$1000
        BEQ processMemoryCheck
        JMP.W handleSystemTransition
; [Memory] Processes memory check results. Entry: 16-bit A/X/Y.
processMemoryCheck:
        LDA.W $1E02
        AND.W #$0001
        BEQ handleSFXCompletion
        JMP.W handleSpecialCondition
; [SFX] Handles sound effect completion. Entry: 16-bit A/X/Y.
handleSFXCompletion:
        LDA.B $00
        BNE updateSFXMemory
        LDA.W $1E02
        CMP.W #$0168
        BCC processSFXCleanup
        JMP.W handleSystemTransition
; [SFX] Updates sound effect memory. Entry: 16-bit A/X/Y.
updateSFXMemory:
        LDA.W #$0024
        STA.W $1288
        JSL.L SetupDataProcessing80
        LDA.W #$0000
        XBA
; [SFX] Processes sound effect cleanup. Entry: 16-bit A/X/Y.
processSFXCleanup:
