        CLC
        ADC.W $1E8B,X
        STA.W $1E8B,X
        LDA.W $058D
        LSR A
        AND.B #$01
        EOR.B #$FF
        INC A
        CLC
        ADC.W $1E8B,X
        STA.W $1E8B,X
; [Music] Handles audio crossfade between tracks. Entry: 8-bit A, 16-bit X/Y.
handleCrossfade:
        CPX.W #$0004
        BCS updateVolumeRamp
        LDA.W $1E8B,X
        AND.B #$01
        STA.W $1E8B,X
        CPX.W #$0003
        BNE handleEchoEffect
        CMP.W $12BE
        BEQ handleEchoEffect
        STA.W $12BE
        JSL.L UpdateCollision
        JMP.W handleEchoEffect
; [Music] Updates volume ramp effects. Entry: 8-bit A, 16-bit X/Y.
updateVolumeRamp:
        CPX.W #$0005
        BNE processPanningEffect
        LDA.W $1E8B,X
        BMI CODE_5FFC96
        CMP.B #$38
        BCC handleEchoEffect
        LDA.B #$37
        STA.W $1E8B,X
        JMP.W handleEchoEffect
; [Music] Processes audio panning effects. Entry: 8-bit A, 16-bit X/Y.
processPanningEffect:
        LDA.W $1E8B,X
        BMI CODE_5FFC96
        CMP.B #$18
        BCC handleEchoEffect
        LDA.B #$17
        STA.W $1E8B,X
        JMP.W handleEchoEffect
CODE_5FFC96:
        STZ.W $1E8B,X
; [Music] Handles echo/reverb effects. Entry: 8-bit A, 16-bit X/Y.
handleEchoEffect:
        LDA.W $1E01
        ASL A
        STA.B $02
        ASL A
        CLC
        ADC.B $02
        TAY
        LDA.B #$30
        STA.B $00
        LDA.B #$14
        STA.B $04
        JSR.W updateFilterEffect
        JSR.W updateChorusEffect
        PLP
        PLB
        RTL
; [Music] Updates audio filter effects. Entry: 8-bit A, 16-bit X/Y.
updateFilterEffect:
        SEP #$20
        LDA.B #$00
        XBA
        INY
        LDX.B $04
; [Music] Processes audio modulation effects. Entry: 8-bit A, 16-bit X/Y.
processModulation:
        LDA.W $FF3F,Y
        BEQ handleTremolo
        STA.B $0A,X
        INY
        INX
        LDA.B $00
        STA.B $0A,X
        INX
        JMP.W processModulation
; [Music] Handles tremolo/vibrato effects. Entry: 8-bit A, 16-bit X/Y.
handleTremolo:
        LDX.W $0F22
        LDA.B #$80
        STA.W $0E22,X
        LDA.B #$9F
        STA.W $0E25,X
        REP #$20
        LDA.B $04
        CLC
        ADC.W #$000A
        STA.W $0E23,X
        LDA.W #$0014
        STA.W $0E26,X
        LDA.W $1E01
        AND.W #$00FF
        TAY
        LDA.W $FF25,Y
        STA.W $0E28,X
        TXA
        CLC
        ADC.W #$0008
        STA.W $0F22
        SEP #$20
        LDA.B #$00
        XBA
        RTS
; [Music] Updates chorus effect processing. Entry: 8-bit A, 16-bit X/Y.
updateChorusEffect:
        LDA.B #$2C
        STA.B $00
        LDA.B #$01
        STA.B $02
        STZ.B $03
; [Music] Processes delay effect. Entry: 8-bit A, 16-bit X/Y.
processDelayEffect:
        LDX.B $02
        CPX.W #$0003
        BEQ handleReverbEffect
        BCS updateDistortion
        LDA.W $1E8B,X
        ASL A
        ASL A
        ASL A
        TAY
        JMP.W processCompression
; [Music] Handles reverb effect processing. Entry: 8-bit A, 16-bit X/Y.
handleReverbEffect:
        LDA.W $1E8B,X
        INC A
        INC A
        ASL A
        ASL A
        ASL A
        TAY
        JMP.W processCompression
; [Music] Updates distortion effect. Entry: 8-bit A, 16-bit X/Y.
updateDistortion:
        LDA.W $1E8B,X
        AND.B #$0F
        STA.B $06
        LDA.W $1E8B,X
        LSR A
        LSR A
        LSR A
        LSR A
        TAY
        LDA.W $FDBB,X
        TAX
        LDA.W $FFBF,Y
        STA.B $00,X
        LDA.B $00
        STA.B $01,X
        LDY.B $06
        LDA.W $FFBF,Y
        STA.B $02,X
        LDA.B $00
        STA.B $03,X
        JMP.W updateNoiseReduction
; [Music] Processes audio compression. Entry: 8-bit A, 16-bit X/Y.
processCompression:
        LDA.W $FDBB,X
        TAX
        STZ.B $04
; [Music] Handles audio limiting/peak control. Entry: 8-bit A, 16-bit X/Y.
handleLimiting:
        LDA.W $FF9F,Y
        STA.B $00,X
        INY
        INX
        LDA.B $00
        STA.B $00,X
        INX
        INC.B $04
        LDA.B $04
        CMP.B #$08
        BNE handleLimiting
; [Music] Updates noise reduction processing. Entry: 8-bit A, 16-bit X/Y.
updateNoiseReduction:
        LDX.W $0F22
        LDA.B #$80
        STA.W $0E22,X
        LDA.B #$9F
        STA.W $0E25,X
        REP #$20
        LDY.B $02
        LDA.W $FDBB,Y
        AND.W #$00FF
        STA.W $0E23,X
        LDA.W $FDC1,Y
        AND.W #$00FF
        STA.W $0E26,X
        LDA.B $02
        DEC A
        ASL A
        TAY
        LDA.W $FF35,Y
        STA.W $0E28,X
        TXA
        CLC
        ADC.W #$0008
        STA.W $0F22
        SEP #$20
        LDA.B #$00
        XBA
        INC.B $02
        LDA.B $02
        CMP.B #$06
        BEQ processEqualization
        JMP.W processDelayEffect
; [Music] Processes audio equalization. Entry: 8-bit A, 16-bit X/Y.
processEqualization:
        RTS
        db $00
        db $40,$48,$50,$60,$68,$00,$06,$06,$10,$04,$04,$E2
        db $20,$A9,$00,$EB,$22,$4E,$8B,$80,$A9,$12,$8D,$CA,$00,$9C,$CB,$00
        db $28,$AB,$6B
; [Music] Handles final audio mix processing. Entry: 8-bit A, 16-bit X/Y.
handleFinalMix:
        PHP
        SEP #$20
        LDA.B #$00
        XBA
        REP #$10
        LDA.W $0080
        ORA.B #$80
        STA.W $2100
        STZ.W $420C
        STZ.W $00C0
        STZ.W $4200
        REP #$20
        JSL.L LoadPaletteData
        LDA.W #$002A
        STA.W $1270
