        JSL.L LoadPaletteData
        LDA.W #$0011
        STA.W $1270
        JSL.L ClearMemoryBlock
        PHB
        LDX.W #$7000
        LDY.W #$0320
        LDA.W #$003F
        MVN $00,$7F
        PLB
        SEP #$20
        LDA.B #$00
