        LDA.B #$02
        STA.W $00A4
        LDA.B #$B3
        STA.W $00A5
        STZ.W $0097
        STZ.W $0098
        STZ.W $0099
        STZ.W $00A2
        STZ.W $00A3
        LDA.B #$12
        STA.W $00A6
        STA.W $00A7
        STA.W $00A8
        REP #$20
        STZ.W $1E02
        STZ.W $0521
        STZ.W $0527
        STZ.W $052D
        LDA.W #$FFE0
        STA.W $0524
        STA.W $052A
        STZ.W $0530
        LDA.W #$00B0
        STA.W $1E04
        LDA.W #$005F
        STA.W $1E06
        JSR.W SetupSpriteAndUI
        LDX.W #$6000
        STX.W $2116
        LDX.W #$0000
; [Init] Clears VRAM and initializes system. Writes zeros to VRAM $2118. Entry: 16-bit A/X/Y.
clearVRAMAndInit:
        STZ.W $2118
        INX
        CPX.W #$0800
        BNE clearVRAMAndInit
        SEP #$20
        LDA.B #$00
        XBA
        JSR.W loadInitialData
        JSL.L InitGameFlags1
        INC.W $00C9
        LDA.B #$81
        STA.W $4200
        PLP
        RTS
; [Init] Loads initial data from ROM tables. Entry: 8-bit A, 16-bit X/Y.
loadInitialData:
        LDY.W #$0000
        STY.B $00
; [Init] Processes data table loading. Entry: 8-bit A, 16-bit X/Y.
processDataTable:
        LDX.W $FF25,Y
        STX.W $2116
        LDX.B $00
        LDA.W $FF3F,X
        STA.B $02
        INX
; [Init] Continues data loading process. Entry: 8-bit A, 16-bit X/Y.
continueDataLoad:
        LDA.W $FF3F,X
        BEQ completeInitialization
        STA.W $2118
        LDA.B $02
        STA.W $2119
        INX
        JMP.W continueDataLoad
; [Init] Completes system initialization. Entry: 8-bit A, 16-bit X/Y.
completeInitialization:
        INX
        STX.B $00
        INY
        INY
        CPY.W #$0010
        BNE processDataTable
        RTS
